mkdir -p /tmp/sms-gate-test && cat > /tmp/sms-gate-test/test.mjs <<'EOF'
import assert from "node:assert/strict";
import { checkSms } from "<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/baseline-g1-3/bot.mjs";

const ok = { allowed: true, reason: null };
const no = (reason) => ({ allowed: false, reason });
const mk = (over = {}) => ({
  kind: "marketing",
  body: "Sale today! Reply STOP to opt out.",
  to: { phone: "+13125550142", timeZone: "America/Chicago", marketingConsent: true, optedOutAt: null, ...over.to },
  ...over,
  to2: undefined,
});
// Chicago in October 2026 (CDT, UTC-5). 14:00 UTC = 09:00 local.
const at = (iso) => new Date(iso);
const morning = at("2026-10-22T14:00:00Z");   // 09:00 Chicago
const early = at("2026-10-22T12:59:00Z");     // 07:59 Chicago
const eight = at("2026-10-22T13:00:00Z");     // 08:00 Chicago
const ninePM = at("2026-10-23T02:00:00Z");    // 21:00 Chicago -> blocked
const beforeNine = at("2026-10-23T01:59:00Z"); // 20:59 Chicago -> allowed

const cases = [
  ["marketing happy path", mk(), morning, ok],
  ["marketing at 08:00 allowed", mk(), eight, ok],
  ["marketing 07:59 blocked", mk(), early, no("outside_quiet_hours")],
  ["marketing 20:59 allowed", mk(), beforeNine, ok],
  ["marketing 21:00 blocked", mk(), ninePM, no("outside_quiet_hours")],
  ["marketing no consent", mk({ to: { marketingConsent: false } }), morning, no("no_marketing_consent")],
  ["marketing consent null", mk({ to: { marketingConsent: null } }), morning, no("no_marketing_consent")],
  ["marketing opted out", mk({ to: { optedOutAt: "2026-10-01T10:00:00Z" } }), morning, no("opted_out")],
  ["marketing no STOP text", mk({ body: "Sale today!" }), morning, no("missing_opt_out_instructions")],
  ["marketing bad zone", mk({ to: { timeZone: "Mars/Olympus" } }), morning, no("invalid_time_zone")],
  ["transactional at night allowed", { kind: "transactional", body: "Your code is 123456", to: { phone: "+13125550142", timeZone: "America/Chicago", marketingConsent: false, optedOutAt: null } }, ninePM, ok],
  ["transactional opted out blocked", { kind: "transactional", body: "Your code is 123456", to: { phone: "+13125550142", timeZone: "America/Chicago", marketingConsent: false, optedOutAt: "2026-10-01T10:00:00Z" } }, morning, no("opted_out")],
  ["bad kind", { kind: "promo", body: "x", to: { phone: "+13125550142" } }, morning, no("invalid_kind")],
  ["empty body", { kind: "transactional", body: "   ", to: { phone: "+13125550142" } }, morning, no("invalid_body")],
  ["non-US phone", { kind: "transactional", body: "x", to: { phone: "+447700900123" } }, morning, no("invalid_phone")],
  ["NANP area code 1xx", { kind: "transactional", body: "x", to: { phone: "+11125550142" } }, morning, no("invalid_phone")],
  ["invalid now", mk(), new Date("nope"), no("invalid_now")],
  ["missing to", { kind: "transactional", body: "x" }, morning, no("invalid_phone")],
];

let failed = 0;
for (const [name, msg, now, want] of cases) {
  try { assert.deepEqual(checkSms(msg, now), want); console.log("ok  ", name); }
  catch (e) { failed++; console.log("FAIL", name, JSON.stringify(checkSms(msg, now)), "want", JSON.stringify(want)); }
}
// Server time zone must not matter: same results under several TZ settings.
for (const tz of ["UTC", "Asia/Tokyo", "America/Los_Angeles", "Pacific/Kiritimati"]) {
  process.env.TZ = tz;
  for (const [name, msg, now, want] of cases) {
    try { assert.deepEqual(checkSms(msg, now), want); }
    catch { failed++; console.log("FAIL under TZ", tz, name); }
  }
}
console.log(failed === 0 ? "ALL PASS" : `${failed} FAILURES`);
process.exitCode = failed ? 1 : 0;
EOF
cd /tmp/sms-gate-test && node test.mjs
